<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'HMAC SHA-256 Generator','description'=>'Generate an HMAC-SHA-256 digest from a message and secret key locally.','url'=>'https://smarttoolz.in/tools/hmac-sha256/']; smarttoolz_tool_page_start($tool); ?><main class="tool"><h1>HMAC SHA-256 Generator</h1><p>Generate an HMAC-SHA-256 signature in your browser.</p><input id="k" placeholder="Secret key"><textarea id="m" placeholder="Message"></textarea><button id="go">Generate HMAC</button><div id="o"></div></main><style>.tool{max-width:760px;margin:60px auto;padding:24px}.tool input,.tool textarea{width:100%;box-sizing:border-box;margin:8px 0;padding:13px;border:1px solid #ddd;border-radius:10px}.tool textarea{min-height:140px}.tool button{padding:12px 18px;border:0;border-radius:10px;background:#5541ff;color:#fff;font-weight:800}.tool #o{margin-top:16px;padding:14px;background:#f6f7fb;border-radius:10px;word-break:break-all;font-family:monospace}</style><script>go.onclick=async()=>{const enc=new TextEncoder(),key=await crypto.subtle.importKey('raw',enc.encode(k.value),{name:'HMAC',hash:'SHA-256'},false,['sign']);const h=await crypto.subtle.sign('HMAC',key,enc.encode(m.value));o.textContent=Array.from(new Uint8Array(h)).map(x=>x.toString(16).padStart(2,'0')).join('')}</script><?php smarttoolz_tool_page_end(); ?>